test("renders comprehensive spec and plan component catalogs", () => {
  const projectRoot = fs.mkdtempSync(path.join(os.tmpdir(), "stenc-component-catalog-"));
  const docsRoot = path.join(projectRoot, "docs", "stenc");
  const specTarget = path.join(docsRoot, "content", "specs", "component-catalog.spec.json");
  const planTarget = path.join(docsRoot, "content", "plans", "component-catalog.plan.json");
  fs.mkdirSync(path.dirname(specTarget), { recursive: true });
  fs.mkdirSync(path.dirname(planTarget), { recursive: true });
  fs.copyFileSync(path.join(REPO_ROOT, "examples-app", "content", "specs", "component-catalog.spec.json"), specTarget);
  fs.copyFileSync(path.join(REPO_ROOT, "examples-app", "content", "plans", "component-catalog.plan.json"), planTarget);
  const result = spawnSync(process.execPath, [SCRIPT_PATH, "--project-root", projectRoot, "--docs-dir", docsRoot, "--skip-install", "--skip-open-docs-script"], { encoding: "utf8" });
  assert.equal(result.status, 0, result.stderr || result.stdout);
  const specHtml = fs.readFileSync(path.join(docsRoot, "specs", "component-catalog", "index.html"), "utf8");
  const planHtml = fs.readFileSync(path.join(docsRoot, "plans", "component-catalog", "index.html"), "utf8");
  for (const token of ["document-summary", "scope-in", "scope-out", "requirements", "approaches", "components", "validation", "supporting-section"]) assert.match(specHtml, new RegExp(token));
  for (const token of ["worker-instructions", "scope-check", "file-structure", "plan-slice", "plan-step", "execution-handoff"]) assert.match(planHtml, new RegExp(token));
});

test("accepts bounded structured diagrams", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "stenc-structured-diagram-valid-"));
  const spec = validSingleSpec();
  spec.body.supportingSections[0].blocks.push(validLayerDiagram(), validFlowDiagram(), validRelationDiagram());
  writeJson(path.join(dir, "structured.spec.json"), spec);
  const result = runValidator(dir);
  assert.equal(result.status, 0, result.stderr);
});

"use strict";

const STRUCTURED_DIAGRAM_TYPES = new Set(["layerDiagram", "flowDiagram", "relationDiagram"]);
const DIAGRAM_ROLES = new Set(["consumer", "surface", "session", "engine", "boundary", "value", "neutral"]);
const DIAGRAM_ID_PATTERN = /^[a-z][a-z0-9-]*$/;
const DISALLOWED_CONTROL = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/;

function isDiagramId(value) {
  return typeof value === "string" && DIAGRAM_ID_PATTERN.test(value);
}

function hasSafeDiagramText(value, { multiline = false } = {}) {
  if (typeof value !== "string" || value.trim().length === 0 || DISALLOWED_CONTROL.test(value)) return false;
  return multiline || (!value.includes("\n") && !value.includes("\t"));
}

module.exports = { STRUCTURED_DIAGRAM_TYPES, DIAGRAM_ROLES, DIAGRAM_ID_PATTERN, isDiagramId, hasSafeDiagramText };

"use strict";

function renderStructuredDiagram(block, escapeHtml) {
  if (block.type === "layerDiagram") return renderLayerDiagram(block, escapeHtml);
  if (block.type === "flowDiagram") return renderFlowDiagram(block, escapeHtml);
  if (block.type === "relationDiagram") return renderRelationDiagram(block, escapeHtml);
  throw new Error(`Unsupported structured diagram type: ${block.type}`);
}

function roleClass(role, escapeHtml) {
  return `diagram-role-${escapeHtml(role)}`;
}

module.exports = { renderStructuredDiagram };

